/* DAWAH X — ahmad, অধ্যায় 27 · খণ্ড 27 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][27]=[[5201,5201,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى فِي بَعْضِ مَغَازِيهِ امْرَأَةً مَقْتُولَةً فَأَنْكَرَ ذَلِكَ ‏ ‏وَنَهَى عَنْ قَتْلِ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""],[5202,5202,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَمَ ‏ ‏يَهُودِيًّا وَيَهُودِيَّةً ‏","","",""],[5203,5203,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَبَّادِ بْنِ جَعْفَرٍ ‏ ‏يَقُولُ ‏ ‏أَمَرْتُ ‏ ‏مُسْلِمَ بْنَ يَسَارٍ ‏ ‏مَوْلَى ‏ ‏نَافِعِ بْنِ عَبْدِ الْحَارِثِ ‏ ‏أَنْ يَسْأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَأَنَا جَالِسٌ بَيْنَهُمَا مَا سَمِعْتَ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَنْ جَرَّ إِزَارَهُ مِنْ الْخُيَلَاءِ شَيْئًا فَقَالَ سَمِعْتُهُ يَقُولُ ‏ ‏لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5204,5204,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَمْزَةَ يَعْنِي السُّكَّرِيَّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ يَعْنِي الصَّائِغَ ‏ ‏عَنِ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْصِلُ بَيْنَ ‏ ‏الْوَتْرِ ‏ ‏وَالشَّفْعِ ‏ ‏بِتَسْلِيمَةٍ وَيُسْمِعُنَاهَا ‏","","",""],[5205,5205,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ أَبِي قُرَّةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ حَالِفًا فَلَا يَحْلِفْ إِلَّا بِاللَّهِ عَزَّ وَجَلَّ وَكَانَتْ ‏ ‏قُرَيْشٌ ‏ ‏تَحْلِفُ بِآبَائِهَا فَقَالَ لَا تَحْلِفُوا بِآبَائِكُمْ ‏","","",""],[5206,5206,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَخْبَرَهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ امْرَأَةً كَانَتْ ‏ ‏تَرْعَى عَلَى آلِ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏غَنَمًا ‏ ‏بِسَلْعٍ ‏ ‏فَخَافَتْ عَلَى شَاةٍ مِنْهَا الْمَوْتَ فَذَبَحَتْهَا بِحَجَرٍ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُمْ بِأَكْلِهَا ‏","","",""],[5207,5207,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏فِي الْمَسْجِدِ أَنَّ ‏ ‏جَارِيَةً ‏ ‏لِكَعْبِ بْنِ مَالِكٍ ‏ ‏كَانَتْ ‏ ‏تَرْعَى غَنَمًا لَهُ ‏ ‏بِسَلْعٍ ‏ ‏فَعَرَضَ لِشَاةٍ مِنْهَا فَخَافَتْ عَلَيْهَا فَأَخَذَتْ ‏ ‏لِخَافَةً ‏ ‏مِنْ حَجَرٍ فَذَبَحَتْهَا بِهَا فَسَأَلُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏ ‏فَأَمَرَهُمْ بِأَكْلِهَا ‏","","",""],[5208,5208,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى أَنْ يُسَافَرَ بِالْمُصْحَفِ إِلَى أَرْضِ الْعَدُوِّ ‏","","",""],[5209,5209,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏يَنْهَى عَنْ بَيْعِ ‏ ‏حَبَلِ الْحَبَلَةِ ‏ ‏وَذَاكَ أَنَّ أَهْلَ الْجَاهِلِيَّةِ كَانُوا يَبِيعُونَ ذَلِكَ الْبَيْعَ فَنَهَاهُمْ عَنْ ذَلِكَ ‏","","",""],[5210,5210,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَرَكَ الْعَصْرَ مُتَعَمِّدًا حَتَّى تَغْرُبَ الشَّمْسُ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[5211,5211,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا نِسَاءَكُمْ الْمَسَاجِدَ وَبُيُوتُهُنَّ خَيْرٌ لَهُنَّ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏ابْنٌ لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏بَلَى وَاللَّهِ لَنَمْنَعُهُنَّ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏تَسْمَعُنِي أُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ مَا تَقُولُ ‏","","",""],[5212,5212,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ عُمَرُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَدْرُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مَرْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي عَائِشَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ غَدَاةٍ بَعْدَ طُلُوعِ الشَّمْسِ فَقَالَ ‏ ‏رَأَيْتُ قُبَيْلَ الْفَجْرِ كَأَنِّي أُعْطِيتُ الْمَقَالِيدَ وَالْمَوَازِينَ فَأَمَّا الْمَقَالِيدُ فَهَذِهِ الْمَفَاتِيحُ وَأَمَّا الْمَوَازِينُ فَهِيَ الَّتِي تَزِنُونَ بِهَا فَوُضِعْتُ فِي كِفَّةٍ وَوُضِعَتْ أُمَّتِي فِي كِفَّةٍ فَوُزِنْتُ بِهِمْ فَرَجَحْتُ ثُمَّ جِيءَ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏فَوُزِنَ بِهِمْ فَوَزَنَ ثُمَّ جِيءَ ‏ ‏بِعُمَرَ ‏ ‏فَوُزِنَ فَوَزَنَ ثُمَّ جِيءَ ‏ ‏بِعُثْمَانَ ‏ ‏فَوُزِنَ بِهِمْ ثُمَّ رُفِعَتْ ‏","","",""],[5213,5213,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَنْبَأَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ الْعُقَيْلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَادَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏وَأَنَا بَيْنَهُ وَبَيْنَ ‏ ‏الْبَدَوِيِّ فَقَالَ يَا رَسُولَ اللَّهِ كَيْفَ صَلَاةُ اللَّيْلِ فَقَالَ ‏ ‏مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الصُّبْحَ فَوَاحِدَةً وَرَكْعَتَيْنِ قَبْلَ ‏ ‏الْغَدَاةِ ‏","","",""],[5214,5214,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْعَوَّامِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا النِّسَاءَ أَنْ يَخْرُجْنَ إِلَى الْمَسَاجِدِ ‏ ‏وَبُيُوتُهُنَّ خَيْرٌ لَهُنَّ ‏","","",""],[5215,5215,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ نَافِعٍ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً ‏ ‏إِنَّ ‏ ‏عُمَرَ بْنَ نَافِعٍ ‏ ‏أَخْبَرَهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَلْبَسُ إِذَا أَحْرَمْنَا قَالَ ‏ ‏لَا تَلْبَسُوا الْقُمُصَ وَلَا السَّرَاوِيلَاتِ وَلَا الْعَمَائِمَ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا الْخِفَافَ إِلَّا أَنْ يَكُونَ رَجُلٌ لَيْسَتْ لَهُ نَعْلَانِ فَيَلْبَسَ الْخُفَّيْنِ وَيَجْعَلَهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ وَلَا تَلْبَسُوا شَيْئًا مِنْ الثِّيَابِ مَسَّهُ ‏ ‏الزَّعْفَرَانُ ‏ ‏وَلَا ‏ ‏الْوَرْسُ ‏","","",""],[5216,5216,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَبَايَعُوا الثَّمَرَ حَتَّى يَبْدُوَ صَلَاحُهُ ‏","","",""],[5217,5217,"","","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَأَخْبَرَنَا ‏ ‏يَعْنِي ‏ ‏يَزِيدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏كَانَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعْتَقَ نَصِيبًا لَهُ فِي إِنْسَانٍ ‏ ‏أَوْ مَمْلُوكٍ ‏ ‏كُلِّفَ عِتْقَ بَقِيَّتِهِ فَإِنْ لَمْ يَكُنْ لَهُ مَالٌ يُعْتِقُهُ بِهِ فَقَدْ جَازَ مَا عَتَقَ ‏","","",""],[5218,5218,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ عَنْ الَّذِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي بِهِ يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏ ‏وَذَكَرَ ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ يَزِيدُ هَؤُلَاءِ الْكَلِمَاتِ مِنْ عِنْدِهِ لَبَّيْكَ ‏ ‏وَالرَّغْبَاءُ ‏ ‏إِلَيْكَ وَالْعَمَلُ لَبَّيْكَ لَبَّيْكَ ‏","","",""],[5219,5219,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّهُ أَخْبَرَهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَمْسٌ لَا ‏ ‏جُنَاحَ ‏ ‏فِي قَتْلِ مَنْ قَتَلَ مِنْهُنَّ الْغُرَابُ وَالْفَأْرَةُ وَالْحِدَأَةُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْعَقْرَبُ ‏","","",""],[5220,5220,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْمَسْجِدَ فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسُ حَوْلَهُ فَأَسْرَعْتُ لِأَسْمَعَ كَلَامَهُ فَتَفَرَّقَ النَّاسُ قَبْلَ أَنْ أَبْلُغَ ‏ ‏وَقَالَ ‏ ‏مَرَّةً قَبْلَ أَنْ أَنْتَهِيَ إِلَيْهِمْ ‏ ‏فَسَأَلْتُ ‏ ‏رَجُلًا ‏ ‏مِنْهُمْ مَاذَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَفَّتِ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[5221,5221,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّهُ أَخْبَرَهُ قَالَ ‏ ‏أَقْبَلْنَا مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏ ‏وَنَحْنُ نَسِيرُ مَعَهُ وَمَعَهُ ‏ ‏حَفْصُ بْنُ عَاصِمِ بْنِ عُمَرَ ‏ ‏وَمُسَاحِقُ بْنُ عَمْرِو بْنِ خِدَاشٍ ‏ ‏فَغَابَتْ لَنَا الشَّمْسُ فَقَالَ أَحَدُهُمَا الصَّلَاةَ فَلَمْ يُكَلِّمْهُ ثُمَّ قَالَ لَهُ الْآخَرُ الصَّلَاةَ فَلَمْ يُكَلِّمْهُ فَقَالَ ‏ ‏نَافِعٌ ‏ ‏فَقُلْتُ لَهُ الصَّلَاةَ فَقَالَ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏عَجِلَ ‏ ‏بِهِ السَّيْرُ جَمَعَ مَا بَيْنَ هَاتَيْنِ الصَّلَاتَيْنِ فَأَنَا أُرِيدُ أَنْ أَجْمَعَ بَيْنَهُمَا قَالَ فَسِرْنَا أَمْيَالًا ثُمَّ نَزَلَ فَصَلَّى ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فَحَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏هَذَا الْحَدِيثَ مَرَّةً أُخْرَى فَقَالَ سِرْنَا إِلَى قَرِيبٍ مِنْ رُبُعِ اللَّيْلِ ثُمَّ نَزَلَ فَصَلَّى ‏","","",""],[5222,5222,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ حَارِثَةَ الْكَلْبِيِّ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏كَانَ يَقُولُ مَا كُنَّا نَدْعُوهُ إِلَّا ‏ ‏زَيْدَ بْنَ مُحَمَّدٍ ‏ ‏حَتَّى نَزَلَ الْقُرْآنُ ‏ { ‏ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ ‏}","","",""],[5223,5223,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ ‏","","",""],[5224,5224,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ مَا نَعْمَلُ فِيهِ أَمْرٌ مُبْتَدَعٌ أَوْ مُبْتَدَأٌ أَوْ أَمْرٌ قَدْ فُرِغَ مِنْهُ قَالَ ‏ ‏أَمْرٌ قَدْ فُرِغَ مِنْهُ فَاعْمَلْ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏فَإِنَّ كُلًّا مُيَسَّرٌ فَأَمَّا مَنْ كَانَ مِنْ أَهْلِ السَّعَادَةِ فَإِنَّهُ يَعْمَلُ لِلسَّعَادَةِ وَمَنْ كَانَ مِنْ أَهْلِ الشَّقَاءِ فَإِنَّهُ يَعْمَلُ لِلشَّقَاءِ ‏","","",""],[5225,5225,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَطَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِذَا رَاحَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏","","",""],[5226,5226,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا رَأَيْتَ أَنَّ الصُّبْحَ يُدْرِكُكَ ‏ ‏فَأَوْتِرْ ‏ ‏بِوَاحِدَةٍ قَالَ فَقِيلَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏مَا مَثْنَى مَثْنَى قَالَ تُسَلِّمُ فِي كُلِّ رَكْعَتَيْنِ ‏","","",""],[5227,5227,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏ ‏وَطَبَّقَ ‏ ‏شُعْبَةُ ‏ ‏يَدَيْهِ ثَلَاثَ مَرَّاتٍ وَكَسَرَ الْإِبْهَامَ فِي الثَّالِثَةِ ‏ ‏قَالَ ‏ ‏عُقْبَةُ ‏ ‏وَأَحْسِبُهُ قَالَ وَالشَّهْرُ ثَلَاثُونَ وَطَبَّقَ كَفَّيْهِ ثَلَاثَ مَرَّاتٍ ‏","","",""],[5228,5228,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ ‏ ‏يَعْنِي لَيْلَةَ الْقَدْرِ ‏ ‏فَإِنْ ضَعُفَ أَحَدُكُمْ أَوْ عَجَزَ فَلَا يُغْلَبَنَّ عَلَى السَّبْعِ الْبَوَاقِي ‏","","",""],[5229,5229,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏أَهَلْ نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ زَعَمُوا ذَلِكَ فَقُلْتُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى فَقَالَ قَدْ زَعَمُوا ذَلِكَ فَقُلْتُ أَنْتَ سَمِعْتَهُ مِنْهُ فَقَالَ قَدْ زَعَمُوا ذَلِكَ فَصَرَفَهُ اللَّهُ عَنِّي وَكَانَ إِذَا قِيلَ لِأَحَدٍ أَنْتَ سَمِعْتَهُ غَضِبَ وَهَمَّ يُخَاصِمُهُ ‏","","",""],[5230,5230,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ يَعْنِي السَّخْتِيَانِيَّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا رَجُلٍ بَاعَ نَخْلًا قَدْ ‏ ‏أُبِّرَتْ ‏ ‏فَثَمَرَتُهَا لِرَبِّهَا الْأَوَّلِ إِلَّا أَنْ يَشْتَرِطَ الْمُبْتَاعُ ‏","","",""],[5231,5231,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَاحَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏","","",""],[5232,5232,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏طَلَّقْتُ امْرَأَتِي وَهِيَ حَائِضٌ فَأَتَى ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا ثُمَّ إِذَا طَهُرَتْ فَلْيُطَلِّقْهَا ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَحَسِبَ تِلْكَ التَّطْلِيقَةَ قَالَ ‏ ‏فَمَهْ ‏","","",""],[5233,5233,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏مَا أَقْرَأُ فِي الرَّكْعَتَيْنِ قَبْلَ الصُّبْحِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِاللَّيْلِ مَثْنَى مَثْنَى وَيُوتِرُ بِرَكْعَةٍ مِنْ آخِرِ اللَّيْلِ قَالَ ‏ ‏أَنَسٌ ‏ ‏قُلْتُ فَإِنَّمَا أَسْأَلُكَ مَا أَقْرَأُ فِي الرَّكْعَتَيْنِ قَبْلَ الصُّبْحِ فَقَالَ بَهْ بَهْ إِنَّكَ ‏ ‏لَضَخْمٌ ‏ ‏إِنَّمَا أُحَدِّثُ ‏ ‏أَوْ قَالَ إِنَّمَا أَقْتَصُّ لَكَ الْحَدِيثَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِاللَّيْلِ رَكْعَتَيْنِ رَكْعَتَيْنِ ثُمَّ ‏ ‏يُوتِرُ ‏ ‏بِرَكْعَةٍ مِنْ آخِرِ اللَّيْلِ ثُمَّ يَقُومُ كَأَنَّ الْأَذَانَ أَوْ الْإِقَامَةَ فِي أُذُنَيْهِ ‏","","",""],[5234,5234,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ رَبِّهِ بْنَ سَعِيدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا رَجُلٍ بَاعَ نَخْلًا قَدْ أُبِّرَتْ فَثَمَرَتُهَا لِلْأَوَّلِ وَأَيُّمَا رَجُلٍ بَاعَ مَمْلُوكًا وَلَهُ مَالٌ فَمَالُهُ لِرَبِّهِ الْأَوَّلِ إِلَّا أَنْ يَشْتَرِطَ الْمُبْتَاعُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَحَدَّثْتُهُ ‏ ‏بِحَدِيثِ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّهُ حَدَّثَ بِالنَّخْلِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمَمْلُوكِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏عَبْدُ رَبِّهِ ‏ ‏لَا أَعْلَمُهُمَا جَمِيعًا إِلَّا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ مَرَّةً أُخْرَى فَحَدَّثَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَشُكَّ ‏","","",""],[5235,5235,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏صَدَقَةَ بْنَ يَسَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏وَقَّتَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّأْمِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏وَلِأَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏ذَاتَ عِرْقٍ ‏ ‏وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏","","",""],[5236,5236,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَحِلُّ لِرَجُلٍ أَنْ يُعْطِيَ الْعَطِيَّةَ ثُمَّ يَرْجِعَ فِيهَا إِلَّا الْوَالِدَ فِيمَا يُعْطِي وَلَدَهُ وَمَثَلُ الَّذِي يُعْطِي الْعَطِيَّةَ ثُمَّ يَرْجِعُ فِيهَا كَمَثَلِ الْكَلْبِ أَكَلَ حَتَّى إِذَا شَبِعَ قَاءَ ثُمَّ عَادَ فِيهِ ‏","","",""],[5237,5237,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْخَالِقِ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏وَقَدْ ذُكِرَ ‏ ‏الْمُزَفَّتُ ‏ ‏عَنْ غَيْرِ ‏ ‏ابْنِ عُمَرَ ‏","","",""],[5238,5238,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكٍ الْهَمْدَانِيَّ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏بِجَمْعٍ ‏ ‏فَأَقَامَ فَصَلَّى الْمَغْرِبَ ثَلَاثًا ثُمَّ صَلَّى الْعِشَاءَ رَكْعَتَيْنِ بِإِقَامَةٍ وَاحِدَةٍ ‏ ‏قَالَ فَسَأَلَهُ ‏ ‏خَالِدُ بْنُ مَالِكٍ ‏ ‏عَنْ ذَلِكَ فَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ مِثْلَ هَذَا فِي هَذَا الْمَكَانِ ‏","","",""],[5239,5239,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْوَلَاءِ ‏ ‏وَعَنْ هِبَتِهِ ‏","","",""],[5240,5240,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَأَلَ ‏ ‏عُمَرُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُصِيبُنِي الْجَنَابَةُ مِنْ اللَّيْلِ فَمَا أَصْنَعُ قَالَ ‏ ‏اغْسِلْ ذَكَرَكَ ثُمَّ تَوَضَّأْ ثُمَّ ارْقُدْ ‏","","",""],[5241,5241,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُنَادِي بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ‏ ‏بِلَالٌ ‏ ‏أَوْ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[5242,5242,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثَّمَرَةِ ‏ ‏أَوْ النَّخْلِ ‏ ‏حَتَّى يَبْدُوَ صَلَاحُهُ ‏ ‏فَقِيلَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏مَا صَلَاحُهُ قَالَ ‏ ‏تَذْهَبُ ‏ ‏عَاهَتُهُ ‏","","",""],[5243,5243,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِيعُهُ حَتَّى يَقْبِضَهُ ‏","","",""],[5244,5244,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَا وَرَجُلٌ آخَرُ فَجَاءَ رَجُلٌ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏اسْتَأْخِرَا فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانُوا ثَلَاثَةً فَلَا يَتَنَاجَى اثْنَانِ دُونَ وَاحِدٍ ‏","","",""],[5245,5245,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ أَمَرَ رَجُلًا إِذَا أَخَذَ مَضْجَعَهُ قَالَ ‏ ‏اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا لَكَ مَمَاتُهَا وَمَحْيَاهَا إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا اللَّهُمَّ أَسْأَلُكَ ‏ ‏الْعَافِيَةَ ‏ ‏فَقَالَ لَهُ رَجُلٌ سَمِعْتَ هَذَا مِنْ ‏ ‏عُمَرَ ‏ ‏فَقَالَ مِنْ خَيْرٍ مِنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5246,5246,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الصُّبْحَ فَاسْجُدْ سَجْدَةً وَرَكْعَتَيْنِ قَبْلَ الصُّبْحِ ‏","","",""],[5247,5247,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏سَمِعْتُ ‏ ‏يُونُسَ بْنَ جُبَيْرٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏طَلَّقْتُ امْرَأَتِي وَهِيَ حَائِضٌ قَالَ فَأَتَى ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَقَالَ ‏ ‏لِيُرَاجِعْهَا فَإِذَا طَهُرَتْ فَإِنْ شَاءَ فَلْيُطَلِّقْهَا ‏ ‏قَالَ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَفَتَحْتَسِبُ بِهَا قَالَ ‏ ‏مَا يَمْنَعُهُ نَعَمْ أَرَأَيْتَ إِنْ عَجَزَ وَاسْتَحْمَقَ ‏","","",""],[5248,5248,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اتَّخَذَ كَلْبًا إِلَّا كَلْبَ زَرْعٍ أَوْ غَنَمٍ أَوْ صَيْدٍ فَإِنَّهُ يَنْقُصُ مِنْ أَجْرِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏","","",""],[5249,5249,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏بِجَمْعٍ ‏ ‏فَأَقَامَ الصَّلَاةَ فَصَلَّى الْمَغْرِبَ ثَلَاثًا وَسَلَّمَ وَصَلَّى الْعَتَمَةَ رَكْعَتَيْنِ وَحَدَّثَ ‏ ‏سَعِيدٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏صَلَّاهَا فِي هَذَا الْمَكَانِ فَصَنَعَ مِثْلَ ذَا ‏ ‏وَحَدَّثَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَ مِثْلَ هَذَا فِي هَذَا الْمَكَانِ ‏","","",""],[5250,5250,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ ارْحَمْ الْمُحَلِّقِينَ قَالُوا وَالْمُقَصِّرِينَ يَا رَسُولَ اللَّهِ قَالَ اللَّهُمَّ ارْحَمْ الْمُحَلِّقِينَ قَالُوا وَالْمُقَصِّرِينَ يَا رَسُولَ اللَّهِ قَالَ اللَّهُمَّ ارْحَمْ الْمُحَلِّقِينَ قَالُوا يَا رَسُولَ اللَّهِ وَالْمُقَصِّرِينَ قَالَ وَالْمُقَصِّرِينَ ‏","","",""],[5251,5251,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَتْ تَلْبِيَةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[5252,5252,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏قَالَ ‏ ‏ذَكَرْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏حَدَّثَهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّى بِالْعُمْرَةِ وَالْحَجِّ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَرْحَمُ اللَّهُ ‏ ‏أَنَسًا ‏ ‏وَهِلَ ‏ ‏أَنَسٌ ‏ ‏وَهَلْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا حُجَّاجًا فَلَمَّا قَدِمْنَا أَمَرَنَا أَنْ نَجْعَلَهَا عُمْرَةً إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏قَالَ ‏ ‏فَحَدَّثْتُ ‏ ‏أَنَسًا ‏ ‏بِذَلِكَ فَغَضِبَ ‏ ‏وَقَالَ ‏ ‏لَا تَعُدُّونَا إِلَّا صِبْيَانًا ‏","","",""],[5253,5253,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏حَبَلِ الْحَبَلَةِ ‏","","",""],[5254,5254,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا حَقُّ امْرِئٍ مُسْلِمٍ لَهُ شَيْءٌ ‏ ‏يُوصِي فِيهِ يَبِيتُ لَيْلَتَيْنِ إِلَّا وَوَصِيَّتُهُ عِنْدَهُ مَكْتُوبَةٌ ‏","","",""],[5255,5255,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَخْبَرَهُمْ ‏ ‏أَنَّ جَارِيَةً كَانَتْ ‏ ‏تَرْعَى لِآلِ ‏ ‏كَعْبِ بْنِ مَالِكٍ الْأَنْصَارِيِّ ‏ ‏غَنَمًا لَهُمْ وَأَنَّهَا خَافَتْ عَلَى شَاةٍ مِنْ الْغَنَمِ أَنْ تَمُوتَ فَأَخَذَتْ حَجَرًا فَذَبَحَتْهَا بِهِ وَأَنَّ ذَلِكَ ذُكِرَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُمْ بِأَكْلِهَا ‏","","",""],[5256,5256,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا حَقُّ امْرِئٍ مُسْلِمٍ يَبِيتُ لَيْلَتَيْنِ وَلَهُ شَيْءٌ يُوصِي فِيهِ إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ ‏","","",""],[5257,5257,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَأْكُلْ أَحَدُكُمْ بِشِمَالِهِ وَلَا يَشْرَبْ بِشِمَالِهِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ وَيَشْرَبُ بِشِمَالِهِ ‏","","",""],[5258,5258,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏رَجُلٌ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي رَجُلٌ أُخْدَعُ فِي الْبَيْعِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏مَنْ بَايَعْتَ فَقُلْ لَا ‏ ‏خِلَابَةَ ‏","","",""],[5259,5259,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏وَعُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَمُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏جَدَّ ‏ ‏بِهِ السَّيْرُ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏وَكَانَ فِي بَعْضِ حَدِيثِهِمَا إِلَى رُبُعِ اللَّيْلِ أَخَّرَهُمَا جَمِيعًا ‏","","",""],[5260,5260,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ السَّخْتِيَانِيِّ ‏ ‏وَأَيُّوبَ بْنِ مُوسَى ‏ ‏وَإِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعَ فِي ‏ ‏مِجَنٍّ ‏ ‏ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ ‏","","",""],[5261,5261,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ لِلْفَرَسِ ‏ ‏سَهْمَيْنِ ‏ ‏وَلِلرَّجُلِ ‏ ‏سَهْمًا ‏ ‏قَالَ وَبَعَثَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏نَحْوَ ‏ ‏تِهَامَةَ ‏ ‏فَأَصَبْنَا غَنِيمَةً فَبَلَغَ ‏ ‏سُهْمَانُنَا ‏ ‏اثْنَيْ عَشَرَ بَعِيرًا ‏ ‏وَنَفَّلَنَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعِيرًا بَعِيرًا ‏","","",""],[5262,5262,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَطَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَخْلَ ‏ ‏بَنِي النَّضِيرِ ‏ ‏وَحَرَّقَ ‏","","",""],[5263,5263,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْعَوْفِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَتَبَايَعُوا الثَّمَرَةَ حَتَّى ‏ ‏يَبْدُوَ ‏ ‏صَلَاحُهَا قَالَ وَمَا بُدُوُّ صَلَاحِهَا قَالَ تَذْهَبُ ‏ ‏عَاهَتُهَا ‏ ‏وَيَخْلُصُ طَيِّبُهَا ‏","","",""],[5264,5264,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي ‏ ‏مَسْجِدَ قُبَاءَ ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[5265,5265,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏سَمِعْتُ ‏ ‏طَاوُسًا ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تَبِيعُوا الثَّمَرَةَ حَتَّى يَبْدُوَ صَلَاحُهَا ‏","","",""],[5266,5266,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَيْمَنَ ‏ ‏يَسْأَلُ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَأَبُو الزُّبَيْرِ ‏ ‏يَسْمَعُ فَقَالَ كَيْفَ ‏ ‏تَرَى فِي رَجُلٍ طَلَّقَ امْرَأَتَهُ حَائِضًا فَقَالَ إِنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏طَلَّقَ امْرَأَتَهُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُرَاجِعْهَا عَلَيَّ وَلَمْ يَرَهَا شَيْئًا وَقَالَ فَرَدَّهَا إِذَا طَهُرَتْ فَلْيُطَلِّقْ ‏ ‏أَوْ ‏ ‏يُمْسِكْ ‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَقَرَأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمْ النِّسَاءَ فَطَلِّقُوهُنَّ ‏} ‏فِي قُبُلِ عِدَّتِهِنَّ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَسَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يَقْرَؤُهَا كَذَلِكَ ‏","","",""],[5267,5267,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ فَذَكَرَ ذَلِكَ إِلَى ‏ ‏عُمَرَ ‏ ‏فَانْطَلَقَ ‏ ‏عُمَرُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُمْسِكْهَا ‏ ‏حَتَّى تَحِيضَ غَيْرَ هَذِهِ الْحَيْضَةِ ثُمَّ تَطْهُرَ فَإِنْ بَدَا لَهُ أَنْ يُطَلِّقَهَا فَلْيُطَلِّقْهَا كَمَا أَمَرَهُ اللَّهُ عَزَّ وَجَلَّ وَإِنْ بَدَا لَهُ أَنْ يُمْسِكَهَا فَلْيُمْسِكْهَا ‏","","",""],[5268,5268,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْكُلْ أَحَدُكُمْ مِنْ أُضْحِيَّتِهِ فَوْقَ ثَلَاثَةِ أَيَّامٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا غَابَتْ الشَّمْسُ مِنْ الْيَوْمِ الثَّالِثِ لَا يَأْكُلُ مِنْ لَحْمِ ‏ ‏هَدْيِهِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏ذَلِكَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏فِي ‏ ‏الْهَدْيِ ‏ ‏وَالضَّحَايَا ‏","","",""],[5269,5269,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي ‏ ‏الْمُحْرِمِ ‏ ‏إِذَا لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ يَقْطَعُهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏","","",""],[5270,5270,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُصَلِّي حَيْثُ تَوَجَّهَتْ بِهِ ‏ ‏رَاحِلَتُهُ ‏ ‏وَيَقُولُ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏","","",""],[5271,5271,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَعْرَابِيًّا نَادَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏تَرَى فِي هَذَا الضَّبِّ فَقَالَ ‏ ‏لَا آكُلُهُ وَلَا أُحَرِّمُهُ ‏","","",""],[5272,5272,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كُنَّا إِذَا ‏ ‏بَايَعْنَا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ يُلَقِّنُنَا هُوَ فِيمَا اسْتَطَعْتَ ‏","","",""],[5273,5273,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَّتَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏وَلِأَهْلِ ‏ ‏الشَّأْمِ ‏ ‏الْجُحْفَةَ ‏ ‏وَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَزَعَمُوا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏","","",""],[5274,5274,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَرْزُقُنَا التَّمْرَ قَالَ وَقَدْ كَانَ أَصَابَ النَّاسَ يَوْمَئِذٍ ‏ ‏جَهْدٌ ‏ ‏فَكُنَّا نَأْكُلُ فَيَمُرُّ عَلَيْنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏وَنَحْنُ نَأْكُلُ فَيَقُولُ لَا ‏ ‏تُقَارِنُوا ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْإِقْرَانِ ‏ ‏إِلَّا أَنْ يَسْتَأْذِنَ الرَّجُلُ أَخَاهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أَرَى فِي ‏ ‏الِاسْتِئْذَانِ إِلَّا أَنَّ الْكَلِمَةَ مِنْ كَلَامِ ‏ ‏ابْنِ عُمَرَ ‏","","",""],[5275,5275,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ مُلْتَمِسًا فَلْيَلْتَمِسْهَا فِي الْعَشْرِ الْأَوَاخِرِ ‏","","",""],[5276,5276,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ جَرَّ ثَوْبًا مِنْ ثِيَابِهِ ‏ ‏مَخِيلَةً ‏ ‏فَإِنَّ اللَّهَ لَا يَنْظُرُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5277,5277,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ هَكَذَا وَطَبَّقَ أَصَابِعَهُ مَرَّتَيْنِ وَكَسَرَ فِي الثَّالِثَةِ الْإِبْهَامَ ‏ ‏يَعْنِي قَوْلَهُ تِسْعٌ وَعِشْرُونَ ‏","","",""],[5278,5278,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَقِيقٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوَتْرِ ‏ ‏قَالَ فَمَشَيْتُ أَنَا وَذَاكَ الرَّجُلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى ‏ ‏وَالْوَتْرُ ‏ ‏رَكْعَةٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَمْ يَقُلْ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[5279,5279,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏أَنَّهُ شَهِدَ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏أَقَامَ ‏ ‏بِجَمْعٍ ‏ ‏قَالَ وَأَحْسِبُهُ وَأَذَّنَ ‏ ‏فَصَلَّى الْمَغْرِبَ ثَلَاثًا ثُمَّ سَلَّمَ فَصَلَّى الْعِشَاءَ رَكْعَتَيْنِ ثُمَّ قَالَ صَنَعَ بِنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏فِي هَذَا الْمَكَانِ مِثْلَ هَذَا وَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏صَنَعَ بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَكَانِ مِثْلَ هَذَا ‏","","",""],[5280,5280,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏كَانَ قَدْ جَعَلَ عَلَيْهِ يَوْمًا ‏ ‏يَعْتَكِفُهُ ‏ ‏فِي الْجَاهِلِيَّةِ فَسَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏ ‏فَأَمَرَهُ أَنْ ‏ ‏يَعْتَكِفَ ‏","","",""],[5281,5281,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَاعَ نَخْلًا قَدْ ‏ ‏أُبِّرَتْ ‏ ‏فَثَمَرَتُهَا لِلْبَائِعِ وَمَنْ بَاعَ عَبْدًا لَهُ مَالٌ فَمَالُهُ لِلْبَائِعِ إِلَّا أَنْ ‏ ‏يَشْتَرِطَ ‏ ‏الْمُبْتَاعُ ‏","","",""],[5282,5282,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْتُلُ ‏ ‏الْمُحْرِمُ ‏ ‏خَمْسًا الْحُدَيَّا وَالْغُرَابَ وَالْفَأْرَةَ وَالْعَقْرَبَ وَالْكَلْبَ ‏ ‏الْعَقُورَ ‏","","",""],[5283,5283,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏الشَّأْمِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنٌ ‏ ‏فَقَالَ النَّاسُ ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏","","",""],[5284,5284,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعَ فِي ‏ ‏مِجَنٍّ ‏ ‏ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ ‏","","",""],[5285,5285,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَسَنِ بْنِ أَتَشٍ ‏ ‏أَخْبَرَنِي ‏ ‏النُّعْمَانُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ سَلْمَانَ ‏ ‏رَجُلٍ مِنْ أَهْلِ ‏ ‏صَنْعَاءَ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏بِمَكَّةَ ‏ ‏فَجَلَسْنَا إِلَى ‏ ‏عَطَاءٍ الْخُرَاسَانِيِّ ‏ ‏إِلَى جَنْبِ جِدَارِ الْمَسْجِدِ فَلَمْ نَسْأَلْهُ وَلَمْ يُحَدِّثْنَا قَالَ ثُمَّ جَلَسْنَا إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏مِثْلَ مَجْلِسِكُمْ هَذَا فَلَمْ نَسْأَلْهُ وَلَمْ يُحَدِّثْنَا قَالَ فَقَالَ مَا بَالُكُمْ لَا تَتَكَلَّمُونَ وَلَا تَذْكُرُونَ اللَّهَ قُولُوا اللَّهُ أَكْبَرُ وَالْحَمْدُ لِلَّهِ وَسُبْحَانَ اللَّهِ وَبِحَمْدِهِ بِوَاحِدَةٍ عَشْرًا وَبِعَشْرٍ مِائَةً مَنْ زَادَ زَادَهُ اللَّهُ وَمَنْ سَكَتَ غَفَرَ لَهُ أَلَا أُخْبِرُكُمْ بِخَمْسٍ سَمِعْتُهُنَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا بَلَى قَالَ ‏ ‏مَنْ ‏ ‏حَالَتْ ‏ ‏شَفَاعَتُهُ ‏ ‏دُونَ ‏ ‏حَدٍّ ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ فَهُوَ مُضَادُّ اللَّهِ فِي أَمْرِهِ وَمَنْ أَعَانَ عَلَى خُصُومَةٍ بِغَيْرِ حَقٍّ فَهُوَ مُسْتَظِلٌّ فِي سَخَطِ اللَّهِ حَتَّى يَتْرُكَ وَمَنْ ‏ ‏قَفَا ‏ ‏مُؤْمِنًا أَوْ مُؤْمِنَةً حَبَسَهُ اللَّهُ فِي ‏ ‏رَدْغَةِ الْخَبَالِ ‏ ‏عُصَارَةِ ‏ ‏أَهْلِ النَّارِ وَمَنْ مَاتَ وَعَلَيْهِ دَيْنٌ أُخِذَ لِصَاحِبِهِ مِنْ حَسَنَاتِهِ لَا دِينَارَ ثَمَّ وَلَا دِرْهَمَ وَرَكْعَتَا الْفَجْرِ حَافِظُوا عَلَيْهِمَا فَإِنَّهُمَا مِنْ الْفَضَائِلِ ‏","","",""],[5286,5286,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَسَنِ بْنِ أَتَشٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُرِيدُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَى عَلَى ‏ ‏عُطَارِدٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَهُوَ يُقِيمُ ‏ ‏حُلَّةً ‏ ‏مِنْ حَرِيرٍ يَبِيعُهَا فَأَتَى ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ رَأَيْتُ ‏ ‏عُطَارِدًا ‏ ‏يَبِيعُ ‏ ‏حُلَّتَهُ ‏ ‏فَاشْتَرِيهَا تَلْبَسْهَا إِذَا أَتَاكَ وُفُودُ النَّاسِ فَقَالَ ‏ ‏إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ‏","","",""],[5287,5287,"","","‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ سَلَّامٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُوقَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا جَعْفَرٍ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏إِذَا سَمِعَ مِنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا أَوْ شَهِدَ مَعَهُ مَشْهَدًا لَمْ ‏ ‏يُقَصِّرْ ‏ ‏دُونَهُ ‏ ‏أَوْ ‏ ‏يَعْدُوهُ ‏ ‏قَالَ فَبَيْنَمَا هُوَ جَالِسٌ ‏ ‏وَعُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏يَقُصُّ عَلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏إِذْ قَالَ ‏ ‏عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏مَثَلُ الْمُنَافِقِ كَمَثَلِ الشَّاةِ بَيْنَ الْغَنَمَيْنِ إِنْ أَقْبَلَتْ إِلَى هَذِهِ الْغَنَمِ نَطَحَتْهَا وَإِنْ أَقْبَلَتْ إِلَى هَذِهِ نَطَحَتْهَا فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏لَيْسَ هَكَذَا فَغَضِبَ ‏ ‏عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏وَفِي الْمَجْلِسِ ‏ ‏عَبْدُ اللَّهِ بْنُ صَفْوَانَ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏كَيْفَ قَالَ رَحِمَكَ اللَّهُ فَقَالَ قَالَ ‏ ‏مَثَلُ الْمُنَافِقِ مَثَلُ الشَّاةِ بَيْنَ ‏ ‏الرَّبِيضَيْنِ ‏ ‏إِنْ أَقْبَلَتْ إِلَى ذَا ‏ ‏الرَّبِيضِ ‏ ‏نَطَحَتْهَا وَإِنْ أَقْبَلَتْ إِلَى ذَا ‏ ‏الرَّبِيضِ ‏ ‏نَطَحَتْهَا فَقَالَ لَهُ رَحِمَكَ اللَّهُ هُمَا وَاحِدٌ قَالَ كَذَا سَمِعْتُ ‏","","",""],[5288,5288,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏الْبَيْتِ ‏ ‏وَسَيَأْتِي مَنْ يَنْهَاكُمْ عَنْهُ فَتَسْمَعُونَ مِنْهُ قَالَ ‏ ‏يَعْنِي ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏جَالِسًا قَرِيبًا مِنْهُ ‏","","",""],[5289,5289,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَهُوَ الرُّقْعَةُ فِي الرَّأْسِ ‏","","",""],[5290,5290,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ الْأَهْوَازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْمَغْرِبِ ‏ ‏وِتْرُ ‏ ‏صَلَاةِ النَّهَارِ فَأَوْتِرُوا صَلَاةَ اللَّيْلِ وَصَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى ‏ ‏وَالْوَتْرُ ‏ ‏رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[5291,5291,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْقَزَعِ ‏ ‏فِي الرَّأْسِ ‏","","",""],[5292,5292,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مُطِيعٍ ‏ ‏فَقَالَ مَرْحَبًا ‏ ‏بِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏ضَعُوا لَهُ وِسَادَةً فَقَالَ إِنَّمَا جِئْتُكَ لِأُحَدِّثَكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏نَزَعَ ‏ ‏يَدًا مَنْ طَاعَةِ اللَّهِ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ لَا حُجَّةَ لَهُ وَمَنْ مَاتَ وَهُوَ مَفَارِقٌ لِلْجَمَاعَةِ فَإِنَّهُ يَمُوتُ مِيتَةً جَاهِلِيَّةً ‏","","",""],[5293,5293,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ قَيْسٍ الْمَأْرِبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ثُمَامَةُ بْنُ شَرَاحِيلَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقُلْنَا مَا صَلَاةُ الْمُسَافِرِ فَقَالَ ‏ ‏رَكْعَتَيْنِ رَكْعَتَيْنِ إِلَّا صَلَاةَ الْمَغْرِبِ ثَلَاثًا قُلْتُ أَرَأَيْتَ إِنْ كُنَّا ‏ ‏بِذِي الْمَجَازِ ‏ ‏قَالَ وَمَا ‏ ‏ذُو الْمَجَازِ ‏ ‏قُلْتُ مَكَانًا نَجْتَمِعُ فِيهِ وَنَبِيعُ فِيهِ وَنَمْكُثُ عِشْرِينَ لَيْلَةً أَوْ خَمْسَ عَشْرَةَ لَيْلَةً قَالَ يَا أَيُّهَا الرَّجُلُ كُنْتُ ‏ ‏بِأَذْرَبِيجَانَ ‏ ‏لَا أَدْرِي قَالَ أَرْبَعَةَ أَشْهُرٍ أَوْ شَهْرَيْنِ ‏ ‏فَرَأَيْتُهُمْ يُصَلُّونَهَا رَكْعَتَيْنِ رَكْعَتَيْنِ وَرَأَيْتُ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُصْبَ ‏ ‏عَيْنِي يُصَلِّيهِمَا رَكْعَتَيْنِ رَكْعَتَيْنِ ثُمَّ ‏ ‏نَزَعَ ‏ ‏هَذِهِ الْآيَةَ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏} ‏حَتَّى فَرَغَ مِنْ الْآيَةِ ‏","","",""],[5294,5294,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏سالِمًا ‏ ‏يَقُولُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُهُ عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏مِمَّا ‏ ‏يَلِي ‏ ‏الْمَقَامَ ‏ ‏رَجُلٌ آدَمُ ‏ ‏سَبْطُ ‏ ‏الرَّأْسِ وَاضِعًا يَدَهُ عَلَى رَجُلَيْنِ ‏ ‏يَسْكُبُ ‏ ‏رَأْسُهُ ‏ ‏أَوْ يَقْطُرُ ‏ ‏فَسَأَلْتُ مَنْ هَذَا فَقِيلَ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏أَوْ ‏ ‏الْمَسِيحُ ابْنُ مَرْيَمَ ‏ ‏لَا أَدْرِي أَيَّ ذَلِكَ قَالَ ‏ ‏ثُمَّ رَأَيْتُ وَرَاءَهُ رَجُلًا أَحْمَرَ ‏ ‏جَعْدَ ‏ ‏الرَّأْسِ أَعْوَرَ عَيْنِ الْيُمْنَى أَشْبَهُ مَنْ رَأَيْتُ مِنْهُ ‏ ‏ابْنُ قَطَنٍ ‏ ‏فَسَأَلْتُ مَنْ هَذَا فَقِيلَ ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏","","",""],[5295,5295,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏سَمِعْتُ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أُتِيتُ وَأَنَا نَائِمٌ ‏ ‏بِقَدَحٍ ‏ ‏مِنْ لَبَنٍ فَشَرِبْتُ مِنْهُ حَتَّى جَعَلَ اللَّبَنُ يَخْرُجُ مِنْ أَظْفَارِي ثُمَّ نَاوَلْتُ ‏ ‏فَضْلِي ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ فَمَا ‏ ‏أَوَّلْتَهُ ‏ ‏قَالَ الْعِلْمُ ‏","","",""],[5296,5296,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَبِيعُ الْإِبِلَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَأَبِيعُ بِالدَّنَانِيرِ وَآخُذُ الدَّرَاهِمَ وَأَبِيعُ بِالدَّرَاهِمِ وَآخُذُ الدَّنَانِيرَ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُرِيدُ أَنْ يَدْخُلَ حُجْرَتَهُ فَأَخَذْتُ بِثَوْبِهِ فَسَأَلْتُهُ فَقَالَ ‏ ‏إِذَا أَخَذْتَ وَاحِدًا مِنْهُمَا بِالْآخَرِ فَلَا يُفَارِقَنَّكَ وَبَيْنَكَ وَبَيْنَهُ بَيْعٌ ‏","","",""],[5297,5297,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ فِي الرَّكْعَةِ الْأُولَى مِنْ صَلَاةِ الظُّهْرِ فَرَأَى أَصْحَابُهُ أَنَّهُ قَرَأَ تَنْزِيلُ ‏ ‏السَّجْدَةِ ‏ ‏قَالَ ‏ ‏وَلَمْ أَسْمَعْهُ مِنْ ‏ ‏أَبِي مِجْلَزٍ ‏","","",""],[5298,5298,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى حِمَارٍ وَوَجْهُهُ قِبَلَ الْمَشْرِقِ تَطَوُّعًا ‏","","",""],[5299,5299,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَسْلَمَ ‏ ‏غَيْلَانُ بْنُ سَلَمَةَ الثَّقَفِيُّ ‏ ‏وَتَحْتَهُ عَشَرُ نِسْوَةٍ فِي الْجَاهِلِيَّةِ وَأَسْلَمْنَ مَعَهُ ‏ ‏فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَخْتَارَ مِنْهُنَّ أَرْبَعًا ‏","","",""],[5300,5300,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَبِيعُ الْإِبِلَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَأَبِيعُ بِالدَّنَانِيرِ وَآخُذُ مَكَانَهَا ‏ ‏الْوَرِقَ ‏ ‏وَأَبِيعُ ‏ ‏بِالْوَرِقِ ‏ ‏فَآخُذُ مَكَانَهَا الدَّنَانِيرَ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْتُهُ ‏ ‏خَارِجًا مِنْ بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ فَقَالَ ‏ ‏لَا بَأْسَ بِهِ بِالْقِيمَةِ ‏","","",""],[5301,5301,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَابْنَ عَبَّاسٍ ‏ ‏حَدَّثَا أَنَّهُمَا ‏ ‏سَمِعَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى أَعْوَادِ الْمِنْبَرِ ‏ ‏لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ ‏ ‏وَدْعِهِمْ ‏ ‏الْجُمُعَاتِ أَوْ ‏ ‏لَيَخْتِمَنَّ ‏ ‏اللَّهُ عَلَى قُلُوبِهِمْ وَلَيُكْتَبُنَّ مِنْ الْغَافِلِينَ ‏","","",""],[5302,5302,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏رَجُلٌ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي أُخْدَعُ فِي الْبَيْعِ قَالَ قُلْ لَا ‏ ‏خِلَابَةَ ‏","","",""],[5303,5303,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو جَنَابٍ يَحْيَى بْنُ أَبِي حَيَّةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُنَا وَمَا صَاحِبُ الدِّينَارِ وَالدِّرْهَمِ بِأَحَقَّ مِنْ أَخِيهِ الْمُسْلِمِ ثُمَّ لَقَدْ رَأَيْتُنَا بِأَخَرَةٍ الْآنَ وَلَلدِّينَارُ وَالدِّرْهَمُ أَحَبُّ إِلَى أَحَدِنَا مِنْ أَخِيهِ الْمُسْلِمِ ‏","","",""],[5304,5304,"","","‏ ‏وَلَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَئِنْ أَنْتُمْ اتَّبَعْتُمْ ‏ ‏أَذْنَابَ ‏ ‏الْبَقَرِ وَتَبَايَعْتُمْ ‏ ‏بِالْعِينَةِ ‏ ‏وَتَرَكْتُمْ الْجِهَادَ فِي سَبِيلِ اللَّهِ لَيُلْزِمَنَّكُمْ اللَّهُ مَذَلَّةً فِي أَعْنَاقِكُمْ ثُمَّ لَا تُنْزَعُ مِنْكُمْ حَتَّى تَرْجِعُونَ إِلَى مَا كُنْتُمْ عَلَيْهِ وَتَتُوبُونَ إِلَى اللَّهِ ‏","","",""],[5305,5305,"","","‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَتَكُونَنَّ هِجْرَةٌ بَعْدَ هِجْرَةٍ إِلَى مُهَاجَرِ أَبِيكُمْ ‏ ‏إِبْرَاهِيمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى لَا يَبْقَى فِي الْأَرَضِينَ إِلَّا شِرَارُ أَهْلِهَا وَتَلْفِظُهُمْ أَرَضُوهُمْ وَتَقْذَرُهُمْ رُوحُ الرَّحْمَنِ عَزَّ وَجَلَّ وَتَحْشُرُهُمْ النَّارُ مَعَ الْقِرَدَةِ وَالْخَنَازِيرِ تَقِيلُ حَيْثُ يَقِيلُونَ وَتَبِيتُ حَيْثُ يَبِيتُونَ وَمَا سَقَطَ مِنْهُمْ فَلَهَا ‏","","",""],[5306,5306,"","","‏ ‏وَلَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُ مِنْ أُمَّتِي قَوْمٌ يُسِيئُونَ الْأَعْمَالَ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حَنَاجِرَهُمْ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏لَا أَعْلَمُ إِلَّا قَالَ يَحْقِرُ أَحَدَكُمْ عَمَلَهُ مِنْ عَمَلِهِمْ ‏ ‏يَقْتُلُونَ أَهْلَ الْإِسْلَامِ فَإِذَا خَرَجُوا فَاقْتُلُوهُمْ ثُمَّ إِذَا خَرَجُوا فَاقْتُلُوهُمْ ثُمَّ إِذَا خَرَجُوا فَاقْتُلُوهُمْ ‏ ‏فَطُوبَى ‏ ‏لِمَنْ قَتَلَهُمْ وَطُوبَى لِمَنْ قَتَلُوهُ كُلَّمَا طَلَعَ مِنْهُمْ قَرْنٌ قَطَعَهُ اللَّهُ عَزَّ وَجَلَّ فَرَدَّدَ ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِشْرِينَ مَرَّةً أَوْ أَكْثَرَ وَأَنَا أَسْمَعُ ‏","","",""],[5307,5307,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا رَجَعَ مِنْ ‏ ‏أُحُدٍ ‏ ‏سَمِعَ نِسَاءَ ‏ ‏الْأَنْصَارِ ‏ ‏يَبْكِينَ عَلَى أَزْوَاجِهِنَّ فَقَالَ لَكِنْ ‏ ‏حَمْزَةُ ‏ ‏لَا ‏ ‏بَوَاكِيَ ‏ ‏لَهُ فَبَلَغَ ذَلِكَ نِسَاءَ ‏ ‏الْأَنْصَارِ ‏ ‏فَجِئْنَ يَبْكِينَ عَلَى ‏ ‏حَمْزَةَ ‏ ‏قَالَ فَانْتَبَهَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ فَسَمِعَهُنَّ وَهُنَّ يَبْكِينَ فَقَالَ ‏ ‏وَيْحَهُنَّ لَمْ يَزَلْنَ يَبْكِينَ بَعْدُ مُنْذُ اللَّيْلَةِ مُرُوهُنَّ فَلْيَرْجِعْنَ وَلَا يَبْكِينَ عَلَى هَالِكٍ بَعْدَ الْيَوْمِ ‏","","",""],[5308,5308,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ خَبَّابٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْفَضْلِ ‏ ‏أَوْ ‏ ‏ابْنُ الْفَضْلِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏كَانَ قَاعِدًا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اللَّهُمَّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ حَتَّى عَدَّ الْعَادُّ بِيَدِهِ مِائَةَ مَرَّةٍ ‏","","",""],[5309,5309,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏تَوْبَةَ الْعَنْبَرِيِّ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏الشَّعْبِيُّ ‏ ‏أَرَأَيْتَ حَدِيثَ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ قَاعَدْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَرِيبًا مِنْ سَنَتَيْنِ أَوْ سَنَةٍ وَنِصْفٍ فَلَمْ أَسْمَعْهُ رَوَى عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرَ هَذَا ‏ ‏قَالَ ‏ ‏كَانَ نَاسٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ ‏ ‏سَعْدٌ ‏ ‏فَذَهَبُوا يَأْكُلُونَ مِنْ لَحْمٍ فَنَادَتْهُمْ امْرَأَةٌ مِنْ بَعْضِ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ لَحْمُ ضَبٍّ فَأَمْسَكُوا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُوا أَوْ اطْعَمُوا فَإِنَّهُ حَلَالٌ وَإِنَّهُ لَا بَأْسَ بِهِ ‏ ‏تَوْبَةُ ‏ ‏الَّذِي شَكَّ فِيهِ ‏ ‏وَلَكِنَّهُ لَيْسَ مِنْ طَعَامِي ‏","","",""],[5310,5310,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏سَمِعْتُ ‏ ‏حَكِيمًا الْحَذَّاءَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏سُئِلَ عَنْ الصَّلَاةِ فِي السَّفَرِ فَقَالَ ‏ ‏رَكْعَتَيْنِ سُنَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5311,5311,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَقِيلِ بْنِ طَلْحَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْخَصِيبِ ‏ ‏قَالَ ‏ ‏كُنْتُ قَاعِدًا فَجَاءَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَقَامَ رَجُلٌ مِنْ مَجْلِسِهِ لَهُ فَلَمْ يَجْلِسْ فِيهِ وَقَعَدَ فِي مَكَانٍ آخَرَ فَقَالَ الرَّجُلُ مَا كَانَ ‏ ‏عَلَيْكَ لَوْ قَعَدْتَ فَقَالَ لَمْ أَكُنْ أَقْعُدُ فِي مَقْعَدِكَ وَلَا مَقْعَدِ غَيْرِكَ بَعْدَ شَيْءٍ شَهِدْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ لَهُ رَجُلٌ مِنْ مَجْلِسِهِ فَذَهَبَ لِيَجْلِسَ فِيهِ ‏ ‏فَنَهَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5312,5312,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي يَعْقُوبَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ أَبِي نُعَيْمٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏وَسَأَلَهُ رَجُلٌ عَنْ شَيْءٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَحْسِبُهُ سَأَلَهُ عَنْ الْمُحْرِمِ يَقْتُلُ الذُّبَابَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَهْلُ ‏ ‏الْعِرَاقِ ‏ ‏يَسْأَلُونَ عَنْ الذُّبَابِ وَقَدْ قَتَلُوا ابْنَ بِنْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمَا رَيْحَانَتِي مِنْ الدُّنْيَا ‏","","",""],[5313,5313,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا جَعْفَرٍ يَعْنِي الْمُؤَذِّنَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُسْلِمٍ أَبِي الْمُثَنَّى ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏كَانَ الْأَذَانُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتَيْنِ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَعْنِي مَرَّتَيْنِ مَرَّتَيْنِ ‏ ‏وَالْإِقَامَةُ مَرَّةً غَيْرَ أَنَّهُ يَقُولُ قَدْ قَامَتْ الصَّلَاةُ قَدْ قَامَتْ الصَّلَاةُ وَكُنَّا إِذَا سَمِعْنَا الْإِقَامَةَ تَوَضَّأْنَا ثُمَّ خَرَجْنَا إِلَى الصَّلَاةِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أَحْفَظُ غَيْرَ هَذَا ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا جَعْفَرٍ ‏ ‏مُؤَذِّنَ ‏ ‏الْعُرْبَانِ ‏ ‏فِي مَسْجِدِ ‏ ‏بَنِي هِلَالٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ أَبِي الْمُثَنَّى ‏ ‏مُؤَذِّنِ ‏ ‏مَسْجِدِ الْجَامِعِ ‏ ‏فَذَكَرَ هَذَا الْحَدِيثَ ‏","","",""],[5314,5314,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ رَزِينٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّجُلِ تَكُونُ لَهُ الْمَرْأَةُ ثُمَّ يُطَلِّقُهَا ثُمَّ يَتَزَوَّجُهَا رَجُلٌ فَيُطَلِّقُهَا قَبْلَ أَنْ يَدْخُلَ بِهَا فَتَرْجِعُ إِلَى زَوْجِهَا الْأَوَّلِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى تَذُوقَ ‏ ‏الْعُسَيْلَةَ ‏","","",""],[5315,5315,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَقَالَ ‏ ‏انْتَبِذُوا ‏ ‏فِي ‏ ‏الْأَسْقِيَةِ ‏","","",""],[5316,5316,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏لَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏سَبْعًا ثُمَّ صَلَّى عِنْدَ ‏ ‏الْمَقَامِ ‏ ‏رَكْعَتَيْنِ ثُمَّ خَرَجَ إِلَى ‏ ‏الصَّفَا ‏ ‏مِنْ الْبَابِ الَّذِي يَخْرُجُ إِلَيْهِ فَطَافَ ‏ ‏بِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏قَالَ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏هُوَ سُنَّةٌ ‏","","",""],[5317,5317,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏يَكَادُ يَلْعَنُ ‏ ‏الْبَيْدَاءَ ‏ ‏وَيَقُولُ ‏ ‏أَحْرَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْمَسْجِدِ ‏","","",""],[5318,5318,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنْ يَكُ مِنْ الشُّؤْمِ شَيْءٌ حَقٌّ فَفِي الْمَرْأَةِ وَالْفَرَسِ وَالدَّارِ ‏","","",""],[5319,5319,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْحُمَّى مِنْ فَيْحِ جَهَنَّمَ فَأَطْفِئُوهَا بِالْمَاءِ ‏ ‏أَوْ بَرِّدُوهَا بِالْمَاءِ ‏","","",""],[5320,5320,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنْهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏مُحَمَّدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا زَالَ ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ ‏ ‏أَوْ قَالَ خَشِيتُ أَنْ يُوَرِّثَهُ ‏","","",""],[5321,5321,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي حَجَّةِ الْوَدَاعِ ‏ ‏وَيْحَكُمْ أَوْ قَالَ ‏ ‏وَيْلَكُمْ لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[5322,5322,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏مُحَمَّدًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُوتِيتُ مَفَاتِيحَ كُلِّ شَيْءٍ إِلَّا الْخَمْسَ إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ ‏ ‏الْغَيْثَ ‏ ‏وَيَعْلَمُ مَا فِي ‏ ‏الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏","","",""],[5323,5323,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏مَرَّ بِرَجُلٍ قَدْ ‏ ‏أَنَاخَ ‏ ‏مَطِيَّتَهُ ‏ ‏وَهُوَ يُرِيدُ أَنْ ‏ ‏يَنْحَرَهَا ‏ ‏فَقَالَ ‏ ‏قِيَامًا مُقَيَّدَةً سُنَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5324,5324,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ عَلِمَ النَّاسُ مَا فِي الْوَحْدَةِ مَا أَعْلَمُ مَا سَرَى رَاكِبٌ بِلَيْلٍ وَحْدَهُ ‏","","",""],[5325,5325,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ طَارِقٍ أَبُو قُرَّةَ الزَّبِيدِيُّ ‏ ‏مِنْ أَهْلِ ‏ ‏زَبِيدٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْحُصَيْبِ ‏ ‏بِالْيَمَنِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَكَانَ قَاصًّا لَهُمْ ‏ ‏عَنْ ‏ ‏مُوسَى يَعْنِي ابْنَ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّقَ نَخْلَ ‏ ‏بَنِي النَّضِيرِ ‏ ‏وَقَطَّعَ ‏","","",""],[5326,5326,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْوَاسِطِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَجْعَلُ فَصَّ خَاتَمِهِ مِمَّا يَلِي بَطْنَ كَفِّهِ ‏","","",""],[5327,5327,"","","‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏غُفْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ أُمَّةٍ ‏ ‏مَجُوسٌ ‏ ‏ومَجُوسُ ‏ ‏أُمَّتِي الَّذِينَ يَقُولُونَ لَا ‏ ‏قَدَرَ ‏ ‏إِنْ مَرِضُوا فَلَا تَعُودُوهُمْ وَإِنْ مَاتُوا فَلَا تَشْهَدُوهُمْ ‏","","",""],[5328,5328,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏صَدَقَةَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ ‏ ‏يُصَلِّي فَلَا يَدَعْ أَحَدًا يَمُرُّ بَيْنَ يَدَيْهِ فَإِنْ أَبَى فَلْيُقَاتِلْهُ فَإِنَّ مَعَهُ الْقَرِينَ ‏","","",""],[5329,5329,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ زَيْدِ بْنِ الْخَطَّابِ ‏ ‏مَاتَ فَأَرَادُوا أَنْ يُخْرِجُوهُ مِنْ اللَّيْلِ لِكَثْرَةِ الزِّحَامِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِنْ أَخَّرْتُمُوهُ إِلَى أَنْ تُصْبِحُوا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الشَّمْسَ تَطْلُعُ بِقَرْنِ شَيْطَانٍ ‏","","",""],[5330,5330,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏مِنْ مَنْزِلهِ فَمَرَرْنَا بِفِتْيَانٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏نَصَبُوا طَيْرًا يَرْمُونَهُ وَقَدْ جَعَلُوا لِصَاحِبِ الطَّيْرِ كُلَّ خَاطِئَةٍ مِنْ نَبْلِهِمْ قَالَ فَلَمَّا رَأَوْا ‏ ‏ابْنَ عُمَرَ ‏ ‏تَفَرَّقُوا فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏مَنْ فَعَلَ هَذَا لَعَنَ اللَّهُ مَنْ فَعَلَ هَذَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ مَنْ اتَّخَذَ شَيْئًا فِيهِ الرُّوحُ ‏ ‏غَرَضًا ‏","","",""],[5331,5331,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُضَمِّرُ ‏ ‏الْخَيْلَ ‏","","",""],[5332,5332,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ قَالَتْ إِنَّهَا حَائِضٌ قَالَ إِنَّهَا لَيْسَتْ فِي كَفِّكِ ‏","","",""],[5333,5333,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُصَلِّي فِي السَّفَرِ إِلَّا رَكْعَتَيْنِ غَيْرَ أَنَّهُ كَانَ ‏ ‏يَتَهَجَّدُ ‏ ‏مِنْ اللَّيْلِ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏فَقُلْتُ ‏ ‏لِسَالِمٍ ‏ ‏كَانَا ‏ ‏يُوتِرَانِ ‏ ‏قَالَ نَعَمْ ‏","","",""],[5334,5334,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَفَرَرْنَا فَأَرَدْنَا أَنْ نَرْكَبَ الْبَحْرَ ثُمَّ أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ نَحْنُ ‏ ‏الْفَرَّارُونَ ‏ ‏فَقَالَ ‏ ‏لَا بَلْ أَنْتُمْ ‏ ‏أَوْ أَنْتُمْ ‏ ‏الْعَكَّارُونَ ‏","","",""],[5335,5335,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏النَّذْرِ ‏ ‏وَقَالَ إِنَّهُ لَا يَأْتِي بِخَيْرٍ وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنْ الْبَخِيلِ ‏","","",""],[5336,5336,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقُمْتُ وَتَرَكْتُ ‏ ‏رَجُلًا ‏ ‏عِنْدَهُ مِنْ ‏ ‏كِنْدَةَ ‏ ‏فَأَتَيْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏قَالَ فَجَاءَ ‏ ‏الْكِنْدِيُّ ‏ ‏فَزِعًا فَقَالَ جَاءَ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَجُلٌ فَقَالَ أَحْلِفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏فَقَالَ لَا وَلَكِنْ احْلِفْ بِرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏فَإِنَّ ‏ ‏عُمَرَ ‏ ‏كَانَ يَحْلِفُ بِأَبِيهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحْلِفْ بِأَبِيكَ ‏ ‏فَإِنَّهُ مَنْ حَلَفَ بِغَيْرِ اللَّهِ فَقَدْ أَشْرَكَ ‏","","",""],[5337,5337,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏أَبِي قُرَّةَ مُوسَى بْنِ طَارِقٍ ‏ ‏قَالَ قَالَ ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا ‏ ‏صَدَرَ ‏ ‏مِنْ الْحَجِّ ‏ ‏أَوْ الْعُمْرَةِ ‏ ‏أَنَاخَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏الَّتِي ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏وَأَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏حَدَّثَهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُعَرِّسُ بِهَا حَتَّى يُصَلِّيَ صَلَاةَ الصُّبْحِ ‏","","",""],[5338,5338,"","","‏ ‏قَالَ ‏ ‏مُوسَى ‏ ‏وَأَخْبَرَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى فِي ‏ ‏مُعَرَّسِهِ ‏ ‏فَقِيلَ لَهُ إِنَّكَ فِي ‏ ‏بَطْحَاءَ ‏ ‏مُبَارَكَةٍ ‏","","",""],[5339,5339,"","","‏ ‏قَالَ ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى ‏ ‏عِنْدَ ‏ ‏الْمَسْجِدِ الصَّغِيرِ الَّذِي دُونَ الْمَسْجِدِ الَّذِي يُشْرِفُ عَلَى ‏ ‏الرَّوْحَاءِ ‏","","",""],[5340,5340,"","","‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْزِلُ تَحْتَ ‏ ‏سَرْحَةِ ‏ ‏الرُّوَيْثَةِ ‏ ‏عَنْ يَمِينِ الطَّرِيقِ فِي مَكَانٍ ‏ ‏بَطْحٍ ‏ ‏سَهْلٍ حِينَ يُفْضِي مِنْ ‏ ‏الْأَكَمَةِ ‏ ‏دُونَ بَرِيدِ ‏ ‏الرُّوَيْثَةِ ‏ ‏بِمِيلَيْنِ وَقَدْ انْكَسَرَ أَعْلَاهَا وَهِيَ قَائِمَةٌ عَلَى سَاقٍ ‏","","",""],[5341,5341,"","","‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى مِنْ وَرَاءِ الْعَرْجِ وَأَنْتَ ذَاهِبٌ عَلَى رَأْسِ خَمْسَةِ أَمْيَالٍ مِنْ الْعَرْجِ فِي مَسْجِدٍ إِلَى هَضْبَةٍ عِنْدَ ذَلِكَ الْمَسْجِدِ قَبْرَانِ ‏ ‏أَوْ ثَلَاثَةٌ ‏ ‏عَلَى الْقُبُورِ رَضْمٌ مِنْ حِجَارَةٍ عَلَى يَمِينِ الطَّرِيقِ عِنْدَ ‏ ‏سَلَامَاتِ ‏ ‏الطَّرِيقِ بَيْنَ أُولَئِكَ ‏ ‏السَّلَامَاتِ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَرُوحُ مِنْ الْعَرْجِ بَعْدَ أَنْ تَمِيلَ الشَّمْسُ ‏ ‏بِالْهَاجِرَةِ ‏ ‏فَيُصَلِّي الظُّهْرَ فِي ذَلِكَ الْمَسْجِدِ ‏","","",""],[5342,5342,"","","‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ تَحْتَ ‏ ‏سَرْحَةٍ ‏ ‏وَقَالَ ‏ ‏غَيْرُ ‏ ‏أَبِي قُرَّةَ ‏ ‏سَرَحَاتٍ ‏ ‏عَنْ يَسَارِ الطَّرِيقِ فِي ‏ ‏مَسِيلٍ ‏ ‏دُونَ هَرْشَا ذَلِكَ ‏ ‏الْمَسِيلُ ‏ ‏لَاصِقٌ عَلَى هَرْشَا ‏ ‏وَقَالَ ‏ ‏غَيْرُهُ لَاصِقٌ ‏ ‏بِكَرَاعِ ‏ ‏هَرْشَا ‏ ‏بَيْنَهُ وَبَيْنَ الطَّرِيقِ قَرِيبٌ مِنْ ‏ ‏غَلْوَةِ ‏ ‏سَهْمٍ ‏","","",""],[5343,5343,"","","‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْزِلُ ‏ ‏بِذِي طُوًى ‏ ‏يَبِيتُ بِهِ حَتَّى يُصَلِّيَ صَلَاةَ الصُّبْحِ حِينَ قَدِمَ إِلَى ‏ ‏مَكَّةَ ‏ ‏وَمُصَلَّى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَلِكَ عَلَى ‏ ‏أَكَمَةٍ ‏ ‏غَلِيظَةٍ لَيْسَ فِي الْمَسْجِدِ الَّذِي بُنِيَ ثَمَّ وَلَكِنْ أَسْفَلَ مِنْ ذَلِكَ عَلَى ‏ ‏أَكَمَةٍ ‏ ‏خَشِنَةٍ غَلِيظَةٍ ‏","","",""],[5344,5344,"","","‏ ‏قَالَ وَأَخْبَرَنِي أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقْبَلَ فُرْضَتَيْ الْجَبَلِ الطَّوِيلِ الَّذِي قِبَلَ ‏ ‏الْكَعْبَةِ ‏ ‏فَجَعَلَ الْمَسْجِدَ الَّذِي بُنِيَ يَمِينًا وَالْمَسْجِدُ بِطَرَفِ ‏ ‏الْأَكَمَةِ ‏ ‏وَمُصَلَّى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْفَلُ مِنْهُ عَلَى ‏ ‏الْأَكَمَةِ ‏ ‏السَّوْدَاءِ يَدَعُ مِنْ ‏ ‏الْأَكَمَةِ ‏ ‏عَشْرَ أَذْرُعٍ أَوْ نَحْوَهَا ثُمَّ ‏ ‏يُصَلِّي مُسْتَقْبِلَ ‏ ‏الْفُرْضَتَيْنِ ‏ ‏مِنْ الْجَبَلِ الطَّوِيلِ الَّذِي بَيْنَهُ وَبَيْنَ ‏ ‏الْكَعْبَةِ ‏","","",""],[5345,5345,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْمُثَنَّى ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏الْأَذَانُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثْنَى مَثْنَى وَالْإِقَامَةُ وَاحِدَةً غَيْرَ أَنَّ الْمُؤَذِّنَ كَانَ إِذَا قَالَ قَدْ قَامَتْ الصَّلَاةُ قَالَ قَدْ قَامَتْ الصَّلَاةُ مَرَّتَيْنِ ‏","","",""],[5346,5346,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ بَعْدَ الْمَغْرِبِ فِي بَيْتِهِ ‏","","",""],[5347,5347,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[5348,5348,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏نَهْشَلِ بْنِ مُجَمِّعٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏لُقْمَانَ الْحَكِيمَ ‏ ‏كَانَ يَقُولُ إِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا اسْتُوْدِعَ شَيْئًا حَفِظَهُ ‏ ‏و قَالَ ‏ ‏مَرَّةً ‏ ‏نَهْشَلٌ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏","","",""],[5349,5349,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏أَخْبَرَنِي ‏ ‏نَهْشَلُ بْنُ مُجَمِّعٍ الضَّبِّيُّ ‏ ‏قَالَ ‏ ‏وَكَانَ مَرْضِيًّا ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏لُقْمَانَ الْحَكِيمَ ‏ ‏كَانَ يَقُولُ إِنَّ اللَّهَ إِذَا اسْتُوْدِعَ شَيْئًا حَفِظَهُ ‏","","",""],[5350,5350,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ فِي ‏ ‏ثَقِيفٍ ‏ ‏كَذَّابًا ‏ ‏وَمُبِيرًا ‏","","",""],[5351,5351,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مِقْسَمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ الْآيَةَ وَهُوَ عَلَى الْمِنْبَرِ ‏ { ‏وَالسَّمَوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ ‏} ‏قَالَ يَقُولُ اللَّهُ أَنَا الْجَبَّارُ أَنَا الْمُتَكَبِّرُ أَنَا الْمَلِكُ أَنَا الْمُتَعَالِي يُمَجِّدُ نَفْسَهُ قَالَ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرَدِّدُهَا حَتَّى رَجَفَ بِهِ الْمِنْبَرُ حَتَّى ظَنَنَّا أَنَّهُ ‏ ‏سَيَخِرُّ ‏ ‏بِهِ ‏","","",""],[5352,5352,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ الْفَجْرِ كَأَنَّ الْأَذَانَ فِي أُذُنَيْهِ ‏","","",""],[5353,5353,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ يَزْدَوَيْهِ ‏ ‏عَنْ ‏ ‏يَعْفُرَ بْنِ رُوذِيٍّ ‏ ‏سَمِعْتُ ‏ ‏عُبَيْدَ بْنَ عُمَيْرٍ ‏ ‏وَهُوَ يَقُصُّ ‏ ‏يَقُولُ ‏ ‏يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُنَافِقِ كَمَثَلِ الشَّاةِ ‏ ‏الرَّابِضَةِ ‏ ‏بَيْنَ ‏ ‏الْغَنَمِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَيْلَكُمْ لَا تَكْذِبُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُنَافِقِ كَمَثَلِ الشَّاةِ ‏ ‏الْعَائِرَةِ ‏ ‏بَيْنَ الْغَنَمَيْنِ ‏","","",""],[5354,5354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شُغِلَ عَنْهَا لَيْلَةً فَأَخَّرَهَا حَتَّى رَقَدْنَا فِي الْمَسْجِدِ ثُمَّ اسْتَيْقَظْنَا ثُمَّ رَقَدْنَا ثُمَّ اسْتَيْقَظْنَا ثُمَّ رَقَدْنَا ثُمَّ اسْتَيْقَظْنَا فَخَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏لَيْسَ أَحَدٌ مِنْ أَهْلِ الْأَرْضِ اللَّيْلَةَ يَنْتَظِرُ الصَّلَاةَ غَيْرُكُمْ ‏","","",""],[5355,5355,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ بْنِ الْهَادِ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أَبَرَّ ‏ ‏الْبِرِّ ‏ ‏صِلَةُ ‏ ‏الْمَرْءِ أَهْلَ وُدِّ أَبِيهِ بَعْدَ أَنْ ‏ ‏يُوَلِّيَ ‏","","",""],[5356,5356,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذِنَ ‏ ‏لِلْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏اسْتَأْذَنَ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَبِيتَ ‏ ‏بِمَكَّةَ ‏ ‏لَيَالِيَ ‏ ‏مِنًى ‏ ‏مِنْ أَجْلِ ‏ ‏سِقَايَتِهِ ‏ ‏فَأَذِنَ لَهُ ‏","","",""],[5357,5357,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَقَ رَأْسَهُ فِي حَجَّةِ الْوَدَاعِ ‏","","",""],[5358,5358,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى صَبِيًّا قَدْ حُلِقَ بَعْضُ شَعَرِهِ وَتُرِكَ بَعْضُهُ فَنَهَى عَنْ ذَلِكَ وَقَالَ ‏ ‏احْلِقُوا كُلَّهُ أَوْ اتْرُكُوا كُلَّهُ ‏","","",""],[5359,5359,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَخِي الزُّهْرِيِّ عَبْدِ اللَّهِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَزَالُ الْمَسْأَلَةُ بِأَحَدِكُمْ حَتَّى يَلْقَى اللَّهَ وَمَا فِي وَجْهِهِ ‏ ‏مُزْعَةُ ‏ ‏لَحْمٍ ‏","","",""],[5360,5360,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَأَبُو بَكْرِ بْنُ سُلَيْمَانَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ صَلَاةَ الْعِشَاءِ فِي آخِرِ حَيَاتِهِ فَلَمَّا سَلَّمَ قَامَ قَالَ أَرَأَيْتُمْ لَيْلَتَكُمْ هَذِهِ عَلَى رَأْسِ مِائَةِ سَنَةٍ مِنْهَا لَا ‏ ‏يَبْقَى مِمَّنْ هُوَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَوَهِلَ ‏ ‏النَّاسُ فِي مَقَالَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِلْكَ فِيمَا يَتَحَدَّثُونَ مِنْ هَذِهِ الْأَحَادِيثِ عَنْ مِائَةِ سَنَةٍ وَإِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبْقَى الْيَوْمَ مِمَّنْ هُوَ عَلَى ظَهْرِ الْأَرْضِ يُرِيدُ أَنْ يَنْخَرِمَ ذَلِكَ الْقَرْنُ ‏","","",""],[5361,5361,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا حَسَدَ إِلَّا عَلَى اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالًا فَهُوَ يُنْفِقُ مِنْهُ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ ‏ ‏وَآنَاءَ ‏ ‏النَّهَارِ وَرَجُلٌ آتَاهُ اللَّهُ الْقُرْآنَ فَهُوَ يَقُومُ بِهِ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ ‏ ‏وَآنَاءَ ‏ ‏النَّهَارِ ‏","","",""],[5362,5362,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَجِدُونَ النَّاسَ كَإِبِلٍ مِائَةٍ لَا يَجِدُ الرَّجُلُ فِيهَا ‏ ‏رَاحِلَةً ‏","","",""],[5363,5363,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عُمَرَ ‏ ‏ثَوْبًا أَبْيَضَ فَقَالَ أَجَدِيدٌ ثَوْبُكَ أَمْ غَسِيلٌ فَقَالَ فَلَا أَدْرِي مَا رَدَّ عَلَيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَسْ جَدِيدًا وَعِشْ حَمِيدًا وَمُتْ شَهِيدًا ‏ ‏أَظُنُّهُ قَالَ وَيَرْزُقُكَ اللَّهُ ‏ ‏قُرَّةَ عَيْنٍ ‏ ‏فِي الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[5364,5364,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَالثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مَسْحَ الرُّكْنِ الْيَمَانِي وَالرُّكْنِ الْأَسْوَدِ ‏ ‏يَحُطُّ ‏ ‏الْخَطَايَا ‏ ‏حَطًّا ‏","","",""],[5365,5365,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْتَلِمُ الرُّكْنَ ‏ ‏الْيَمَانِيَ وَلَا يَسْتَلِمُ الْآخَرَيْنِ ‏","","",""],[5366,5366,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَقَ فِي حَجَّتِهِ ‏","","",""],[5367,5367,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏يَنْزِلُونَ ‏ ‏بِالْأَبْطَحِ ‏","","",""],[5368,5368,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُقِمْ أَحَدُكُمْ أَخَاهُ فَيَجْلِسَ فِي مَجْلِسِهِ ‏ ‏قَالَ ‏ ‏سَالِمٌ ‏ ‏فَكَانَ الرَّجُلُ يَقُومُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏مِنْ مَجْلِسِهِ فَمَا يَجْلِسُ فِي مَجْلِسِهِ ‏","","",""],[5369,5369,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِذَا بَلَغَ الرَّجُلُ الْمُسْلِمُ أَرْبَعِينَ سَنَةً آمَنَهُ اللَّهُ مِنْ أَنْوَاعِ الْبَلَايَا مِنْ الْجُنُونِ وَالْبَرَصِ ‏ ‏وَالْجُذَامِ ‏ ‏وَإِذَا بَلَغَ الْخَمْسِينَ لَيَّنَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ حِسَابَهُ وَإِذَا بَلَغَ السِّتِّينَ رَزَقَهُ اللَّهُ إِنَابَةً يُحِبُّهُ عَلَيْهَا وَإِذَا بَلَغَ السَّبْعِينَ أَحَبَّهُ اللَّهُ وَأَحَبَّهُ أَهْلُ السَّمَاءِ وَإِذَا بَلَغَ الثَّمَانِينَ تَقَبَّلَ اللَّهُ مِنْهُ حَسَنَاتِهِ وَمَحَا عَنْهُ سَيِّئَاتِهِ وَإِذَا بَلَغَ التِّسْعِينَ غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ وَسُمِّيَ أَسِيرَ اللَّهِ فِي الْأَرْضِ وَشُفِّعَ فِي أَهْلِهِ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْعَامِرِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[5370,5370,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْتَرِي الذَّهَبَ بِالْفِضَّةِ أَوْ الْفِضَّةَ بِالذَّهَبِ قَالَ ‏ ‏إِذَا اشْتَرَيْتَ وَاحِدًا مِنْهُمَا بِالْآخَرِ فَلَا يُفَارِقْكَ صَاحِبُكَ وَبَيْنَكَ وَبَيْنَهُ ‏ ‏لَبْسٌ ‏","","",""],[5371,5371,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ رُؤْيَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّاسَ اجْتَمَعُوا فَقَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَزَعَ ذَنُوبًا أَوْ ذَنُوبَيْنِ وَفِي نَزْعِهِ ضَعْفٌ وَاللَّهُ يَغْفِرُ لَهُ ثُمَّ قَامَ ‏ ‏ابْنُ الْخَطَّابِ ‏ ‏فَاسْتَحَالَتْ ‏ ‏غَرْبًا ‏ ‏فَمَا رَأَيْتُ عَبْقَرِيًّا مِنْ النَّاسِ ‏ ‏يَفْرِي ‏ ‏فَرِيَّهُ ‏ ‏حَتَّى ضَرَبَ النَّاسُ بِعَطَنٍ ‏","","",""],[5372,5372,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَمَّرَ ‏ ‏أُسَامَةَ ‏ ‏بَلَغَهُ أَنَّ النَّاسَ يَعِيبُونَ ‏ ‏أُسَامَةَ ‏ ‏وَيَطْعَنُونَ فِي إِمَارَتِهِ فَقَامَ ‏ ‏كَمَا حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏فَقَالَ ‏ ‏إِنَّكُمْ تَعِيبُونَ ‏ ‏أُسَامَةَ ‏ ‏وَتَطْعَنُونَ فِي إِمَارَتِهِ وَقَدْ فَعَلْتُمْ ذَلِكَ فِي أَبِيهِ مِنْ قَبْلُ وَإِنْ كَانَ ‏ ‏لَخَلِيقًا ‏ ‏لِلْإِمَارَةِ وَإِنْ كَانَ لَأَحَبَّ النَّاسِ كُلِّهِمْ إِلَيَّ وَإِنَّ ابْنَهُ هَذَا بَعْدَهُ مِنْ أَحَبِّ النَّاسِ إِلَيَّ فَاسْتَوْصُوا بِهِ خَيْرًا فَإِنَّهُ مِنْ خِيَارِكُمْ ‏","","",""],[5373,5373,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ لَقِيَ ‏ ‏زَيْدَ بْنَ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏بِأَسْفَلِ بَلْدَحَ وَذَلِكَ قَبْلَ أَنْ يَنْزِلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَحْيُ فَقَدَّمَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُفْرَةً ‏ ‏فِيهَا لَحْمٌ فَأَبَى أَنْ يَأْكُلَ مِنْهُ وَقَالَ ‏ ‏إِنِّي لَا آكُلُ مِمَّا تَذْبَحُونَ عَلَى ‏ ‏أَنْصَابِكُمْ ‏ ‏وَلَا آكُلُ مِمَّا لَمْ يُذْكَرْ اسْمُ اللَّهِ عَلَيْهِ ‏","","",""],[5374,5374,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏أُتِيَ وَهُوَ فِي ‏ ‏الْمُعَرَّسِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏فَقِيلَ لَهُ إِنَّكَ ‏ ‏بِبَطْحَاءَ ‏ ‏مُبَارَكَةٍ ‏","","",""],[5375,5375,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏عَدَدْتُ ‏ ‏شَيْبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوًا مِنْ عِشْرِينَ شَعَرَةً ‏","","",""],[5376,5376,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْحَضَرِ وَالسَّفَرِ ‏ ‏فَصَلَّى الظُّهْرَ فِي الْحَضَرِ أَرْبَعًا وَبَعْدَهَا رَكْعَتَيْنِ وَصَلَّى الْعَصْرَ أَرْبَعًا وَلَيْسَ بَعْدَهَا شَيْءٌ وَصَلَّى الْمَغْرِبَ ثَلَاثًا وَبَعْدَهَا رَكْعَتَيْنِ وَصَلَّى الْعِشَاءَ أَرْبَعًا وَصَلَّى فِي السَّفَرِ الظُّهْرَ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ وَالْعَصْرَ رَكْعَتَيْنِ وَلَيْسَ بَعْدَهَا شَيْءٌ وَالْمَغْرِبَ ثَلَاثًا وَبَعْدَهَا رَكْعَتَيْنِ وَالْعِشَاءَ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ ‏","","",""],[5377,5377,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هَانِئٍ ‏ ‏عَنْ ‏ ‏عَبَّاسٍ الْحَجْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ لِي خَادِمًا يُسِيءُ وَيَظْلِمُ أَفَأَضْرِبُهُ قَالَ ‏ ‏تَعْفُو عَنْهُ كُلَّ يَوْمٍ سَبْعِينَ مَرَّةً ‏","","",""],[5378,5378,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُمَرَ يَعْنِي عَبْدَ الْجَبَّارِ الْأَيْلِيَّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي سُمَيَّةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَأَلَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏وَهِيَ أُمُّ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏تَرَى الْمَرْأَةُ فِي الْمَنَامِ مَا يَرَى الرَّجُلُ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَتْ الْمَرْأَةُ ذَلِكَ وَأَنْزَلَتْ فَلْتَغْتَسِلْ ‏","","",""],[5379,5379,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ الْعَمِّيِّ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ نِسَاءَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلْنَهُ عَنْ ‏ ‏الذَّيْلِ ‏ ‏فَقَالَ ‏ ‏اجْعَلْنَهُ شِبْرًا فَقُلْنَ إِنَّ شِبْرًا لَا يَسْتُرُ مِنْ عَوْرَةٍ فَقَالَ اجْعَلْنَهُ ذِرَاعًا فَكَانَتْ إِحْدَاهُنَّ إِذَا أَرَادَتْ أَنْ تَتَّخِذَ دِرْعًا أَرْخَتْ ذِرَاعًا فَجَعَلَتْهُ ذَيْلًا ‏","","",""],[5380,5380,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ حَمْزَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏أَنَّ شَاعِرًا قَالَ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَبِلَالُ ‏ ‏عَبْدُ اللَّهِ خَيْرُ ‏ ‏بِلَالِ ‏ ‏فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏كَذَبْتَ ذَاكَ ‏ ‏بِلَالُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5381,5381,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏صَدِيقٌ مِنْ أَهْلِ ‏ ‏الشَّأْمِ ‏ ‏يُكَاتِبُهُ فَكَتَبَ إِلَيْهِ مَرَّةً ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏إِنَّهُ بَلَغَنِي أَنَّكَ تَكَلَّمْتَ فِي شَيْءٍ مِنْ ‏ ‏الْقَدَرِ ‏ ‏فَإِيَّاكَ أَنْ تَكْتُبَ إِلَيَّ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَكُونُ فِي أُمَّتِي أَقْوَامٌ يُكَذِّبُونَ بِالْقَدَرِ ‏","","",""],[5382,5382,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا النِّسَاءَ حُظُوظَهُنَّ مِنْ الْمَسَاجِدِ إِذَا اسْتَأْذَنَّكُمْ ‏ ‏فَقَالَ ‏ ‏بِلَالٌ ‏ ‏وَاللَّهِ لَنَمْنَعُهُنَّ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ لَنَمْنَعُهُنَّ ‏","","",""],[5383,5383,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ الْهَادِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّارُ عَدُوٌّ فَاحْذَرُوهَا ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَتَتَبَّعُ نِيرَانَ أَهْلِهِ فَيُطْفِئُهَا قَبْلَ أَنْ يَبِيتَ ‏","","",""],[5384,5384,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏شَامِنَا ‏ ‏ويَمَنِنَا ‏ ‏مَرَّتَيْنِ فَقَالَ رَجُلٌ وَفِي مَشْرِقِنَا يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ هُنَالِكَ يَطْلُعُ قَرْنُ الشَّيْطَانِ وَلَهَا تِسْعَةُ أَعْشَارِ الشَّرِّ ‏","","",""],[5385,5385,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْحُرِّ بْنِ الصَّيَّاحِ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ الْخَمِيسَ ‏ ‏مِنْ أَوَّلِ الشَّهْرِ ‏ ‏وَالِاثْنَيْنِ الَّذِي يَلِيهِ ‏ ‏وَالِاثْنَيْنِ الَّذِي يَلِيهِ ‏","","",""],[5386,5386,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُصْمٍ أَبِي عَلْوَانَ الْحَنَفِيِّ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي ‏ ‏ثَقِيفٍ ‏ ‏كَذَّابًا ‏ ‏وَمُبِيرًا ‏","","",""],[5387,5387,"","","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَدْخُلُوا عَلَى الْقَوْمِ الْمُعَذَّبِينَ إِلَّا أَنْ تَكُونُوا بَاكِينَ أَنْ يُصِيبَكُمْ مَا أَصَابَهُمْ ‏","","",""],[5388,5388,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ مَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ عَزَّ وَجَلَّ فِي حَاجَتِهِ وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ ‏ ‏كُرْبَةً ‏ ‏فَرَّجَ اللَّهُ عَزَّ وَجَلَّ عَنْهُ بِهَا ‏ ‏كُرْبَةً ‏ ‏مِنْ ‏ ‏كُرَبِ ‏ ‏يَوْمِ الْقِيَامَةِ وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[5389,5389,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ ‏ { ‏كَشَجَرَةٍ طَيِّبَةٍ ‏} ‏قَالَ هِيَ الَّتِي لَا تَنْفُضُ وَرَقَهَا ‏ ‏وَظَنَنْتُ أَنَّهَا النَّخْلَةُ ‏","","",""],[5390,5390,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ ‏","","",""],[5391,5391,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏ثُوَيْرٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ ‏ ‏الْمُخَنَّثِينَ ‏ ‏مِنْ الرِّجَالِ وَالْمُتَرَجِّلَاتِ مِنْ النِّسَاءِ ‏","","",""],[5392,5392,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ الْحَدَّادُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْوَحْدَةِ أَنْ يَبِيتَ الرَّجُلُ وَحْدَهُ أَوْ يُسَافِرَ وَحْدَهُ ‏","","",""],[5393,5393,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ مِنْكُمْ مُلْتَمِسًا فَلْيَلْتَمِسْ فِي الْعَشْرِ الْأَوَاخِرِ وَإِنْ ضَعُفَ أَحَدُكُمْ أَوْ غُلِبَ فَلَا يُغْلَبْ عَلَى السَّبْعِ الْبَوَاقِي ‏","","",""],[5394,5394,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ تَلَقِّي السِّلَعِ حَتَّى يُهْبَطَ بِهَا الْأَسْوَاقُ ‏","","",""],[5395,5395,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ أَعْرَابِيًّا مَرَّ عَلَيْهِ وَهُمْ فِي طَرِيقِ الْحَجِّ فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَلَسْتَ فُلَانَ بْنَ فُلَانٍ قَالَ بَلَى قَالَ فَانْطَلَقَ إِلَى حِمَارٍ كَانَ يَسْتَرِيحُ عَلَيْهِ إِذَا مَلَّ رَاحِلَتَهُ وَعِمَامَةٍ كَانَ يَشُدُّ بِهَا رَأْسَهُ فَدَفَعَهَا إِلَى الْأَعْرَابِيِّ فَلَمَّا انْطَلَقَ قَالَ لَهُ بَعْضُنَا انْطَلَقْتَ إِلَى حِمَارِكَ الَّذِي كُنْتَ تَسْتَرِيحُ عَلَيْهِ وَعِمَامَتِكَ الَّتِي كُنْتَ تَشُدُّ بِهَا رَأْسَكَ فَأَعْطَيْتَهُمَا هَذَا الْأَعْرَابِيَّ وَإِنَّمَا كَانَ هَذَا ‏ ‏يَرْضَى بِدِرْهَمٍ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏أَبَرَّ ‏ ‏الْبِرِّ ‏ ‏صِلَةُ ‏ ‏الْمَرْءِ أَهْلَ وُدِّ أَبِيهِ بَعْدَ أَنْ ‏ ‏يُوَلِّيَ ‏","","",""],[5396,5396,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَادٌ أَبُو نُوحٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏جَلَبَ ‏ ‏وَلَا ‏ ‏جَنَبَ ‏ ‏وَلَا ‏ ‏شِغَارَ ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[5397,5397,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَمَى ‏ ‏النَّقِيعَ ‏ ‏لِخَيْلِهِ ‏","","",""],[5398,5398,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَبَّقَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الْخَيْلِ وَأَعْطَى السَّابِقَ ‏","","",""],[5399,5399,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَجْلِسُ بَيْنَ الْخُطْبَتَيْنِ ‏","","",""],[5400,5400,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ امْرَأَةً وُجِدَتْ فِي بَعْضِ مَغَازِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْتُولَةً ‏ ‏فَأَنْكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَتْلَ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""]];
